gaJg(){return"Second rounds tend to win."},
gaJh(){return"No re-entries yet."},
gaJi(){return"No symbol has been bought again after a full exit."},
gaJj(){return"Too few second rounds to read."},
aJk(a,b,c){var s=null,r=this.a,q=A.av(b,s,r,s,"symbol","symbols",s,s),p=""+a,o=A.av(a,s,r,s,p+" round",p+" rounds",s,s)
return A.w(c)+" "+q+" bought again after a full exit, "+o+" so far."},
